 46→/**
 47→ * Validate public key format: must be 0x04 prefix + 128 hex chars (64 bytes body = 65 bytes total uncompressed).
 48→ */
 49→function isValidPublicKey(key: string): boolean {
 50→  if (!key.startsWith('0x04')) return false;
 51→  // 0x + 130 hex chars = 65 bytes uncompressed secp256k1
 52→  const hexPart = key.slice(2);
 53→  if (hexPart.length !== 130) return false;
 54→  return /^[0-9a-fA-F]+$/.test(hexPart);
 55→}
 56→
 57→/**
