 59→ */
 60→function truncateKey(key: string): string {
 61→  if (key.length < 12) return key;
 62→  const hex = key.startsWith('0x') ? key.slice(2) : key;
 63→  return `0x${hex.slice(0, 4)}...${hex.slice(-4)}`;
