 66→/**
 67→ * Collect all descendant keys from a folder for sharing.
 68→ * Traverses subfolders depth-first, re-wrapping each file and subfolder key
 69→ * for the recipient.
 70→ *
 71→ * @param children - Children of the current folder
 72→ * @param folderKey - Decrypted AES key of the current folder (for resolving file metadata)
 73→ * @param ownerPrivateKey - Owner's secp256k1 private key for unwrapping ECIES keys
 74→ * @param recipientPubKeyBytes - Recipient's uncompressed secp256k1 public key
 75→ * @param onProgress - Callback for progress tracking
 76→ */
 77→async function collectChildKeys(
 78→  children: FolderChild[],
 79→  folderKey: Uint8Array,
 80→  ownerPrivateKey: Uint8Array,
 81→  recipientPubKeyBytes: Uint8Array,
 82→  onProgress: (wrapped: number) => void
 83→): Promise<ChildKeyDto[]> {
 84→  const childKeys: ChildKeyDto[] = [];
 85→  let wrapped = 0;
 86→
 87→  for (const child of children) {
 88→    if (child.type === 'file') {
 89→      const fp = child as FilePointer;
 90→      // Resolve file metadata to get fileKeyEncrypted, then re-wrap for recipient
 91→      try {
 92→        const { metadata: fileMeta } = await resolveFileMetadata(fp.fileMetaIpnsName, folderKey);
 93→        const reWrappedFileKey = await reWrapEncryptedKey(
 94→          fileMeta.fileKeyEncrypted,
 95→          ownerPrivateKey,
 96→          recipientPubKeyBytes
 97→        );
 98→        childKeys.push({
 99→          keyType: 'file' as ChildKeyDto['keyType'],
100→          itemId: fp.id,
101→          encryptedKey: reWrappedFileKey,
102→        });
103→        wrapped++;
104→        onProgress(wrapped);
105→      } catch (err) {
106→        console.error(`Failed to re-wrap file key for ${fp.name}:`, err);
107→        // Continue with other children
108→      }
109→    } else {
110→      const folder = child as FolderEntry;
111→      // Re-wrap the subfolder's folderKey for the recipient
112→      const folderKeyRewrapped = await reWrapEncryptedKey(
113→        folder.folderKeyEncrypted,
114→        ownerPrivateKey,
115→        recipientPubKeyBytes
116→      );
117→      childKeys.push({
118→        keyType: 'folder' as ChildKeyDto['keyType'],
119→        itemId: folder.id,
120→        encryptedKey: folderKeyRewrapped,
121→      });
122→      wrapped++;
123→      onProgress(wrapped);
124→
125→      // Recurse into subfolder: resolve its metadata and collect its children
126→      try {
127→        const resolved = await resolveIpnsRecord(folder.ipnsName);
128→        if (resolved) {
129→          const folderKeyBytes = await unwrapKey(
130→            hexToBytes(folder.folderKeyEncrypted),
131→            ownerPrivateKey
132→          );
133→          try {
134→            const encryptedBytes = await fetchFromIpfs(resolved.cid);
135→            const encryptedJson = new TextDecoder().decode(encryptedBytes);
136→            const encrypted = JSON.parse(encryptedJson);
137→            const metadata = await decryptFolderMetadata(encrypted, folderKeyBytes);
138→
139→            const subKeys = await collectChildKeys(
140→              metadata.children,
141→              folderKeyBytes,
142→              ownerPrivateKey,
143→              recipientPubKeyBytes,
144→              (subWrapped) => {
145→                onProgress(wrapped + subWrapped);
146→              }
147→            );
148→            wrapped += subKeys.length;
149→            childKeys.push(...subKeys);
150→          } finally {
151→            folderKeyBytes.fill(0);
152→          }
153→        }
154→      } catch (err) {
155→        console.error(`Failed to traverse subfolder ${folder.name}:`, err);
156→        // Continue with other children
157→      }
158→    }
159→  }
160→
161→  return childKeys;
162→}
