166→ */
167→async function reWrapEncryptedKey(
168→  encryptedKeyHex: string,
169→  ownerPrivateKey: Uint8Array,
170→  recipientPubKey: Uint8Array
171→): Promise<string> {
172→  const plainKey = await unwrapKey(hexToBytes(encryptedKeyHex), ownerPrivateKey);
173→  try {
174→    const rewrapped = await wrapKey(plainKey, recipientPubKey);
175→    return bytesToHex(rewrapped);
176→  } finally {
