  1→import { ReactNode, useEffect, useRef, useCallback } from 'react';
  2→import { Portal } from './Portal';
  3→import { MatrixBackground } from '../MatrixBackground';
  4→import { incrementModalCount, decrementModalCount } from '../../hooks/useModalOpen';
  5→import '../../styles/modal.css';
  6→
  7→type ModalProps = {
  8→  open: boolean;
  9→  onClose?: () => void;
 10→  children: ReactNode;
 11→  title?: string;
 12→  /** Optional class applied to the backdrop for variant styling */
 13→  className?: string;
 14→};
 15→
 16→/**
 17→ * Reusable modal dialog component.
 18→ * Features:
 19→ * - Renders in portal outside component tree
 20→ * - Backdrop with optional click-to-close
 21→ * - Close button (X) when onClose provided
 22→ * - Escape key closes when onClose provided
 23→ * - Focus trap: prevents tab from leaving modal
 24→ * - Accessible: aria-modal, role="dialog"
 25→ */
 26→export function Modal({ open, onClose, children, title, className }: ModalProps) {
 27→  const modalRef = useRef<HTMLDivElement>(null);
 28→  const previousActiveElement = useRef<Element | null>(null);
 29→
 30→  // Handle escape key
 31→  const handleKeyDown = useCallback(
 32→    (event: KeyboardEvent) => {
 33→      if (event.key === 'Escape' && onClose) {
 34→        onClose();
 35→      }
 36→    },
 37→    [onClose]
 38→  );
 39→
 40→  // Focus trap: keep focus within modal
 41→  const handleFocusTrap = useCallback((event: KeyboardEvent) => {
 42→    if (event.key !== 'Tab' || !modalRef.current) return;
 43→
 44→    const focusableElements = modalRef.current.querySelectorAll<HTMLElement>(
 45→      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
 46→    );
 47→
 48→    if (focusableElements.length === 0) return;
 49→
 50→    const firstElement = focusableElements[0];
 51→    const lastElement = focusableElements[focusableElements.length - 1];
 52→
 53→    if (event.shiftKey) {
 54→      // Shift+Tab: if on first element, move to last
 55→      if (document.activeElement === firstElement) {
 56→        event.preventDefault();
 57→        lastElement.focus();
 58→      }
 59→    } else {
 60→      // Tab: if on last element, move to first
 61→      if (document.activeElement === lastElement) {
 62→        event.preventDefault();
 63→        firstElement.focus();
 64→      }
 65→    }
 66→  }, []);
 67→
 68→  // Track modal open state for app-level matrix pause
 69→  useEffect(() => {
 70→    if (!open) return;
 71→    incrementModalCount();
 72→    return () => decrementModalCount();
 73→  }, [open]);
 74→
 75→  useEffect(() => {
 76→    if (!open) return;
 77→
 78→    // Store currently focused element
 79→    previousActiveElement.current = document.activeElement;
 80→
 81→    // Focus first focusable element in modal
 82→    const focusableElements = modalRef.current?.querySelectorAll<HTMLElement>(
 83→      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
 84→    );
 85→    if (focusableElements && focusableElements.length > 0) {
 86→      focusableElements[0].focus();
 87→    }
 88→
 89→    // Add event listeners
 90→    document.addEventListener('keydown', handleKeyDown);
 91→    document.addEventListener('keydown', handleFocusTrap);
 92→
 93→    // Cleanup
 94→    return () => {
 95→      document.removeEventListener('keydown', handleKeyDown);
 96→      document.removeEventListener('keydown', handleFocusTrap);
 97→      // Restore focus on close
 98→      if (previousActiveElement.current instanceof HTMLElement) {
 99→        previousActiveElement.current.focus();
100→      }
101→    };
102→  }, [open, handleKeyDown, handleFocusTrap]);
103→
104→  if (!open) {
105→    return null;
106→  }
107→
108→  const handleBackdropClick = (event: React.MouseEvent) => {
109→    // Only close if clicking the backdrop itself, not the modal content
110→    if (event.target === event.currentTarget && onClose) {
111→      onClose();
112→    }
113→  };
114→
115→  return (
116→    <Portal>
117→      <div
118→        className={`modal-backdrop${className ? ` ${className}` : ''}`}
119→        onClick={handleBackdropClick}
120→      >
121→        <MatrixBackground opacity={0.35} className="matrix-canvas--modal" frameInterval={50} />
122→        <div
123→          ref={modalRef}
124→          className="modal-container"
125→          role="dialog"
126→          aria-modal="true"
127→          aria-labelledby={title ? 'modal-title' : undefined}
128→        >
129→          {(title || onClose) && (
130→            <div className="modal-header">
131→              {title && (
132→                <h2 id="modal-title" className="modal-title">
133→                  {title}
134→                </h2>
135→              )}
136→              {onClose && (
137→                <button
138→                  type="button"
139→                  className="modal-close"
140→                  onClick={onClose}
141→                  aria-label="Close modal"
142→                >
143→                  &times;
144→                </button>
145→              )}
146→            </div>
147→          )}
148→          <div className="modal-body">{children}</div>
149→        </div>
150→      </div>
151→    </Portal>
152→  );
153→}
