/**
 * Invite Landing Page Styles - Terminal Aesthetic
 *
 * Full-viewport centered layout with branded card for
 * invite link landing page. Mirrors Login page patterns.
 */

/* ==========================================================================
   Page Layout
   ========================================================================== */

.invite-page {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: var(--spacing-md);
}

/* ==========================================================================
   Card Container
   ========================================================================== */

.invite-card {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 480px;
  padding: var(--spacing-xl) var(--spacing-lg);
  background-color: var(--color-surface);
  border: var(--border-thickness) solid var(--color-green-dim);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-md);
}

.invite-card--error {
  border-color: #ef4444;
}

/* ==========================================================================
   Card Title / Branding
   ========================================================================== */

.invite-card__title {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-bold);
  color: var(--color-green-primary);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin: 0;
}

.invite-card__tagline {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  letter-spacing: 0.05em;
  margin-top: calc(-1 * var(--spacing-xs));
}

/* ==========================================================================
   Card Message
   ========================================================================== */

.invite-card__message {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-sm);
  color: var(--color-text-primary);
  text-align: center;
  line-height: 1.5;
}

.invite-card__sub-message {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-align: center;
  line-height: 1.5;
}

/* ==========================================================================
   Auth Area
   ========================================================================== */

.invite-card__auth-area {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.invite-card__auth-methods {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.invite-card__auth-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
}

/* ==========================================================================
   Loading / Claiming / Success States
   ========================================================================== */

.invite-card__loading {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  text-align: center;
}

.invite-card__claiming {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-sm);
  color: var(--color-green-primary);
  text-align: center;
}

.invite-card__success {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-sm);
  color: var(--color-green-primary);
  text-align: center;
}

/* ==========================================================================
   Error State
   ========================================================================== */

.invite-card__error {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-sm);
  color: #ef4444;
  text-align: center;
  line-height: 1.5;
}

.invite-card__error-detail {
  font-family: var(--font-family-mono);
  font-size: var(--font-size-xs);
  color: var(--color-text-muted);
  text-align: center;
}

/* ==========================================================================
   Buttons
   ========================================================================== */

.invite-card__home-btn {
  padding: var(--spacing-xs) var(--spacing-md);
  font-family: var(--font-family-mono);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  color: var(--color-green-primary);
  background: transparent;
  border: var(--border-thickness) solid var(--color-green-dim);
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.invite-card__home-btn:hover {
  background-color: var(--color-green-darker);
  border-color: var(--color-green-primary);
