  1→import { test, expect, Browser } from '@playwright/test';
  2→import {
  3→  createTestAccount,
  4→  closeTestAccounts,
  5→  navigateToShared,
  6→  navigateToFiles,
  7→  type TestAccount,
  8→} from '../utils/multi-account';
  9→import { createTestTextFile, createTestImageFile, cleanupTestFiles } from '../utils/test-files';
 10→import { FileListPage } from '../page-objects/file-browser/file-list.page';
 11→import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
 12→import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';
 13→import { CreateFolderDialogPage } from '../page-objects/dialogs/create-folder-dialog.page';
 14→import { ShareDialogPage } from '../page-objects/dialogs/share-dialog.page';
 15→import { SharedFileBrowserPage } from '../page-objects/file-browser/shared-file-browser.page';
 16→
 17→/**
 18→ * Sharing Workflow E2E Test Suite
 19→ *
 20→ * Tests user-to-user sharing with multiple authenticated accounts.
 21→ * Each test account gets its own browser context (isolated cookies/storage).
 22→ *
 23→ * Accounts:
 24→ * - Alice: primary sharer (creates content and shares it)
 25→ * - Bob: primary recipient (receives and browses shared content)
 26→ * - Charlie: secondary recipient (for multi-recipient tests)
 27→ *
 28→ * Test flow:
 29→ * 1. Setup: Create 3 accounts, Alice creates test content
 30→ * 2. Basic sharing: Alice shares file with Bob, Bob receives it
 31→ * 3. Folder sharing: Alice shares folder tree, Bob navigates it
 32→ * 4. Multi-recipient: Alice adds Charlie to existing share
 33→ * 5. Revocation: Alice revokes Bob's access
 34→ * 6. Post-share mutations: Alice adds files to shared folder
 35→ * 7. Error cases: Invalid key, self-share, user not found
 36→ * 8. Hide share: Bob hides a shared item
 37→ */
 38→test.describe.serial('Sharing Workflow', () => {
 39→  let browser: Browser;
 40→  let alice: TestAccount;
 41→  let bob: TestAccount;
 42→  let charlie: TestAccount;
 43→
 44→  // Page objects per account
 45→  let aliceFileList: FileListPage;
 46→  let aliceUploadZone: UploadZonePage;
 47→  let aliceContextMenu: ContextMenuPage;
 48→  let aliceCreateFolderDialog: CreateFolderDialogPage;
 49→  let aliceShareDialog: ShareDialogPage;
 50→
 51→  let bobSharedBrowser: SharedFileBrowserPage;
 52→  let bobContextMenu: ContextMenuPage;
 53→
 54→  let charlieSharedBrowser: SharedFileBrowserPage;
 55→
 56→  // Test data - unique per run
 57→  const runId = Date.now().toString();
 58→
 59→  // Shared file
 60→  const sharedFileName = `shared-file-${runId}.txt`;
 61→  const sharedFileContent = 'This file is shared with Bob';
 62→
 63→  // Shared folder structure
 64→  const sharedFolderName = `shared-folder-${runId}`;
 65→  const subFolderName = `subfolder-${runId}`;
 66→  const folderFile1Name = `folder-file1-${runId}.txt`;
 67→  const folderFile2Name = `subfolder-file-${runId}.txt`;
 68→
 69→  // Post-share file (added after share is created)
 70→  const postShareFileName = `added-after-share-${runId}.txt`;
 71→  const postShareFileContent = 'This file was added after the share was created';
 72→
 73→  // Preview test files (image in shared folder)
 74→  const sharedImageName = `test-image-${runId}.png`;
 75→
 76→  // Helper to truncate a public key for matching in the UI
 77→  function truncateKey(key: string): string {
 78→    const hex = key.startsWith('0x') ? key.slice(2) : key;
 79→    return `0x${hex.slice(0, 4)}...${hex.slice(-4)}`;
 80→  }
 81→
 82→  // ============================================
 83→  // Alice helpers
 84→  // ============================================
 85→
 86→  async function aliceCreateFolder(name: string): Promise<void> {
 87→    const newFolderButton = alice.page.locator('.file-browser-new-folder-button');
 88→    await newFolderButton.click();
 89→    await aliceCreateFolderDialog.waitForOpen();
 90→    await aliceCreateFolderDialog.createFolder(name);
 91→    await aliceFileList.waitForItemToAppear(name, { timeout: 30000 });
 92→  }
 93→
 94→  async function aliceUploadFile(fileName: string, content: string): Promise<void> {
 95→    const testFile = createTestTextFile(fileName, content);
 96→    await aliceUploadZone.uploadFile(testFile.path);
 97→
 98→    // Wait for upload: check for either the file appearing or an error alert
 99→    await Promise.race([
100→      aliceFileList.waitForItemToAppear(fileName, { timeout: 30000 }),
101→      alice.page
102→        .locator('[role="alert"]')
103→        .waitFor({ state: 'visible', timeout: 30000 })
104→        .then(async () => {
105→          const alertText = await alice.page.locator('[role="alert"]').textContent();
106→          throw new Error(`Upload failed with alert: ${alertText}`);
107→        }),
108→    ]);
109→  }
110→
111→  async function aliceNavigateIntoFolder(name: string): Promise<void> {
112→    await aliceFileList.doubleClickFolder(name);
113→    // Wait for breadcrumbs to show the folder name
114→    await alice.page.locator('.breadcrumb-item', { hasText: name.toLowerCase() }).waitFor({
115→      state: 'visible',
116→      timeout: 30000,
117→    });
118→  }
119→
120→  async function aliceNavigateBack(): Promise<void> {
121→    await alice.page.locator('[data-testid="parent-dir-row"]').dblclick();
122→    await alice.page.waitForTimeout(500);
123→  }
124→
125→  async function aliceOpenShareDialog(itemName: string): Promise<void> {
126→    await aliceFileList.rightClickItem(itemName);
127→    await aliceContextMenu.waitForOpen();
128→    await aliceContextMenu.clickShare();
129→    await aliceShareDialog.waitForOpen();
130→    await aliceShareDialog.waitForRecipientsLoaded();
131→  }
132→
133→  // ============================================
134→  // Setup and Teardown
135→  // ============================================
136→
137→  test.beforeAll(async ({ browser: testBrowser }) => {
138→    browser = testBrowser;
139→  });
140→
141→  test.afterAll(async () => {
142→    cleanupTestFiles();
143→    if (alice || bob || charlie) {
144→      await closeTestAccounts([alice, bob, charlie].filter(Boolean));
145→    }
146→  });
147→
148→  // ============================================
149→  // Phase 1: Account Setup
150→  // ============================================
151→
152→  test('1.1 Create test accounts (Alice, Bob, Charlie)', async () => {
153→    // Create accounts sequentially (each needs its own context + vault init)
154→    alice = await createTestAccount(browser, 'alice', runId);
155→    bob = await createTestAccount(browser, 'bob', runId);
156→    charlie = await createTestAccount(browser, 'charlie', runId);
157→
158→    // Initialize page objects for Alice
159→    aliceFileList = new FileListPage(alice.page);
160→    aliceUploadZone = new UploadZonePage(alice.page);
161→    aliceContextMenu = new ContextMenuPage(alice.page);
162→    aliceCreateFolderDialog = new CreateFolderDialogPage(alice.page);
163→    aliceShareDialog = new ShareDialogPage(alice.page);
164→
165→    // Initialize page objects for Bob
166→    bobSharedBrowser = new SharedFileBrowserPage(bob.page);
167→    bobContextMenu = new ContextMenuPage(bob.page);
168→
169→    // Initialize page objects for Charlie
170→    charlieSharedBrowser = new SharedFileBrowserPage(charlie.page);
171→
172→    // Verify all three accounts have different public keys
173→    expect(alice.publicKey).not.toBe(bob.publicKey);
174→    expect(alice.publicKey).not.toBe(charlie.publicKey);
175→    expect(bob.publicKey).not.toBe(charlie.publicKey);
176→  });
177→
178→  // ============================================
179→  // Phase 2: Alice Creates Content
180→  // ============================================
181→
182→  test('2.1 Alice creates a test file at root', async () => {
183→    await aliceUploadFile(sharedFileName, sharedFileContent);
184→    expect(await aliceFileList.isItemVisible(sharedFileName)).toBe(true);
185→  });
186→
187→  test('2.2 Alice creates a folder with nested content', async () => {
188→    // Create top-level folder
189→    await aliceCreateFolder(sharedFolderName);
190→    expect(await aliceFileList.isItemVisible(sharedFolderName)).toBe(true);
191→
192→    // Navigate into it and add a file + an image
193→    await aliceNavigateIntoFolder(sharedFolderName);
194→    await aliceUploadFile(folderFile1Name, 'File inside shared folder');
195→
196→    // Upload a PNG image (needed for shared preview test in Phase 11)
197→    const testImage = createTestImageFile(sharedImageName);
198→    await aliceUploadZone.uploadFile(testImage.path);
199→    await aliceFileList.waitForItemToAppear(sharedImageName, { timeout: 30000 });
200→
201→    // Create subfolder
202→    await aliceCreateFolder(subFolderName);
203→
204→    // Navigate into subfolder and add a file
205→    await aliceNavigateIntoFolder(subFolderName);
206→    await aliceUploadFile(folderFile2Name, 'File inside subfolder');
207→
208→    // Navigate back to root
209→    await aliceNavigateBack(); // back to shared folder
210→    await aliceNavigateBack(); // back to root
211→  });
212→
213→  // ============================================
214→  // Phase 3: Basic File Sharing
215→  // ============================================
216→
217→  test('3.1 Alice shares a file with Bob', async () => {
218→    await aliceOpenShareDialog(sharedFileName);
219→
220→    // Should start with no recipients
221→    expect(await aliceShareDialog.getRecipientCount()).toBe(0);
222→
223→    // Share with Bob
224→    await aliceShareDialog.shareWithKey(bob.publicKey);
225→    const successText = await aliceShareDialog.waitForSuccess({ timeout: 30000 });
226→    expect(successText).toContain(truncateKey(bob.publicKey));
227→
228→    // Verify recipient appears in the list
229→    expect(await aliceShareDialog.getRecipientCount()).toBe(1);
230→    const recipientKeys = await aliceShareDialog.getRecipientKeys();
231→    expect(recipientKeys[0]).toBe(truncateKey(bob.publicKey));
232→
233→    await aliceShareDialog.close();
234→  });
235→
236→  test('3.2 Bob sees the shared file in ~/shared', async () => {
237→    await navigateToShared(bob);
238→
239→    // Wait for the shared items to load
240→    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });
241→
242→    // Bob should see Alice's shared file
243→    await bobSharedBrowser.waitForSharedItem(sharedFileName, { timeout: 15000 });
244→    expect(await bobSharedBrowser.getSharedItemCount()).toBeGreaterThanOrEqual(1);
245→
246→    // Verify [RO] badge
247→    const roBadge = bobSharedBrowser.getReadOnlyBadge(sharedFileName);
248→    expect(await roBadge.isVisible()).toBe(true);
249→
250→    // Verify "SHARED BY" shows Alice's truncated key
251→    const sharedBy = await bobSharedBrowser.getSharedBy(sharedFileName);
252→    expect(sharedBy).toContain(truncateKey(alice.publicKey));
253→  });
254→
255→  // ============================================
256→  // Phase 4: Folder Sharing with Descendants
257→  // ============================================
258→
259→  test('4.1 Alice shares a folder with Bob', async () => {
260→    // Make sure Alice is on files page
261→    await navigateToFiles(alice);
262→    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });
263→
264→    await aliceOpenShareDialog(sharedFolderName);
265→
266→    // Share with Bob - folder sharing re-wraps descendant keys
267→    await aliceShareDialog.shareWithKey(bob.publicKey);
268→
269→    // Wait for progress (folder sharing re-wraps keys for each child)
270→    // The progress may be very fast for small folders, so we just wait for success
271→    const successText = await aliceShareDialog.waitForSuccess({ timeout: 60000 });
272→    expect(successText).toContain(truncateKey(bob.publicKey));
273→
274→    await aliceShareDialog.close();
275→  });
276→
277→  test('4.2 Bob navigates the shared folder tree', async () => {
278→    // Navigate to Bob's shared view
279→    await navigateToShared(bob);
280→    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });
281→
282→    // Find and open the shared folder
283→    await bobSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
284→
285→    // Click the shared item and wait — IPNS resolution can be slow on first access
286→    await bobSharedBrowser.openSharedItem(sharedFolderName);
287→    await bob.page.waitForTimeout(3000);
288→
289→    // If IPNS resolution failed on first try, retry once
290→    const parentDirVisible = await bobSharedBrowser.parentDirRow().isVisible();
291→    if (!parentDirVisible) {
292→      await navigateToShared(bob);
293→      await bobSharedBrowser.waitForLoaded({ timeout: 30000 });
294→      await bobSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
295→      await bobSharedBrowser.navigateIntoFolder(sharedFolderName);
296→    }
297→
298→    // Should see folder contents: the file and subfolder
299→    const itemNames = await bobSharedBrowser.getFolderItemNames();
300→    expect(itemNames.some((n) => n.includes(folderFile1Name))).toBe(true);
301→    expect(itemNames.some((n) => n.includes(subFolderName))).toBe(true);
302→
303→    // Navigate into subfolder
304→    await bobSharedBrowser.doubleClickFolderItem(subFolderName);
305→    // Wait for subfolder content to load
306→    await bob.page.waitForTimeout(2000);
307→
308→    const subItems = await bobSharedBrowser.getFolderItemNames();
309→    expect(subItems.some((n) => n.includes(folderFile2Name))).toBe(true);
310→
311→    // Navigate back to shared root
312→    await bobSharedBrowser.navigateToRoot();
313→    await bobSharedBrowser.waitForLoaded({ timeout: 15000 });
314→  });
315→
316→  // ============================================
317→  // Phase 5: Multi-Recipient (Add Charlie)
318→  // ============================================
319→
320→  test('5.1 Alice adds Charlie as a second recipient', async () => {
321→    await navigateToFiles(alice);
322→    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });
323→
324→    await aliceOpenShareDialog(sharedFolderName);
325→
326→    // Bob should already be a recipient
327→    await aliceShareDialog.waitForRecipientsLoaded();
328→    expect(await aliceShareDialog.getRecipientCount()).toBe(1);
329→
330→    // Add Charlie
331→    await aliceShareDialog.shareWithKey(charlie.publicKey);
332→    const successText = await aliceShareDialog.waitForSuccess({ timeout: 60000 });
333→    expect(successText).toContain(truncateKey(charlie.publicKey));
334→
335→    // Now should have 2 recipients
336→    expect(await aliceShareDialog.getRecipientCount()).toBe(2);
337→
338→    await aliceShareDialog.close();
339→  });
340→
341→  test('5.2 Charlie sees the shared folder', async () => {
342→    await navigateToShared(charlie);
343→    await charlieSharedBrowser.waitForLoaded({ timeout: 30000 });
344→
345→    await charlieSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
346→    expect(await charlieSharedBrowser.getSharedItemCount()).toBeGreaterThanOrEqual(1);
347→  });
348→
349→  // ============================================
350→  // Phase 6: Revoke Access
351→  // ============================================
352→
353→  test("6.1 Alice revokes Bob's access to the shared folder", async () => {
354→    await navigateToFiles(alice);
355→    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });
356→
357→    await aliceOpenShareDialog(sharedFolderName);
358→    await aliceShareDialog.waitForRecipientsLoaded();
359→
360→    // Should have 2 recipients (Bob + Charlie)
361→    expect(await aliceShareDialog.getRecipientCount()).toBe(2);
362→
363→    // Revoke Bob
364→    const bobTruncated = truncateKey(bob.publicKey);
365→    await aliceShareDialog.revokeRecipient(bobTruncated);
366→
367→    // Should now have 1 recipient (Charlie only)
368→    expect(await aliceShareDialog.getRecipientCount()).toBe(1);
369→
370→    await aliceShareDialog.close();
371→  });
372→
373→  test('6.2 Bob no longer sees the shared folder', async () => {
374→    // Reload Bob's shared view to get fresh data
375→    await navigateToShared(bob);
376→    await bobSharedBrowser.waitForLoaded({ timeout: 30000 });
377→
378→    // The shared folder should no longer appear for Bob
379→    // (may still show the shared file from test 3.1)
380→    const itemNames = await bobSharedBrowser.getSharedItemNames();
381→    const hasFolderShare = itemNames.some((n) => n.includes(sharedFolderName));
382→    expect(hasFolderShare).toBe(false);
383→  });
384→
385→  test('6.3 Charlie still has access', async () => {
386→    await navigateToShared(charlie);
387→    await charlieSharedBrowser.waitForLoaded({ timeout: 30000 });
388→
389→    await charlieSharedBrowser.waitForSharedItem(sharedFolderName, { timeout: 15000 });
390→    expect(await charlieSharedBrowser.getSharedItemCount()).toBeGreaterThanOrEqual(1);
391→  });
392→
393→  // ============================================
394→  // Phase 7: Post-Share Mutations
395→  // ============================================
396→
397→  test('7.1 Alice adds a file to the shared folder after sharing', async () => {
398→    await navigateToFiles(alice);
399→    await aliceFileList.waitForItemToAppear(sharedFolderName, { timeout: 15000 });
400→
401→    // Navigate into the shared folder
402→    await aliceNavigateIntoFolder(sharedFolderName);
403→
404→    // Upload a new file
405→    await aliceUploadFile(postShareFileName, postShareFileContent);
406→    expect(await aliceFileList.isItemVisible(postShareFileName)).toBe(true);
407→
408→    // Navigate back
409→    await aliceNavigateBack();
410→  });
411→
412→  test('7.2 Charlie sees the newly added file', async () => {
413→    // Wait briefly for any background operations from 7.1 to settle
414→    await charlie.page.waitForTimeout(2000);
415→
416→    // Navigate Charlie into the shared folder to check for the new file
417→    await navigateToShared(charlie);
418→    await charlieSharedBrowser.waitForLoaded({ timeout: 30000 });
419→
420→    await charlieSharedBrowser.navigateIntoFolder(sharedFolderName);
421→
422→    // Wait for folder contents - the new file should be visible
423→    const itemNames = await charlieSharedBrowser.getFolderItemNames();
424→    expect(itemNames.some((n) => n.includes(postShareFileName))).toBe(true);
425→
426→    await charlieSharedBrowser.navigateToRoot();
427→  });
428→
429→  test('7.3 Charlie can preview the post-share file (re-wrapping verification)', async () => {
