import { ApiProperty } from '@nestjs/swagger';

/**
 * Response for creating or listing invites (sharer's view).
 */
export class InviteResponseDto {
  @ApiProperty({ description: 'Invite token (URL-safe base64)' })
  token!: string;

  @ApiProperty({ enum: ['folder', 'file'] })
  itemType!: string;

  @ApiProperty({ description: 'IPNS name of the shared item' })
  ipnsName!: string;

  @ApiProperty({ description: 'Display name of the shared item' })
  itemName!: string;

  @ApiProperty({ enum: ['active', 'claimed', 'revoked'] })
  status!: string;

  @ApiProperty({ description: 'When the invite expires' })
  expiresAt!: Date;

  @ApiProperty({ description: 'When the invite was created' })
  createdAt!: Date;
}

/**
 * Response for the public invite status check (no auth required).
 * Returns only the status -- opaque before authentication.
 */
export class InviteStatusResponseDto {
  @ApiProperty({
    enum: ['active', 'expired', 'claimed', 'revoked'],
    description: 'Current status of the invite',
  })
  status!: string;
}

/**
 * Response for the authenticated invite data fetch (claim flow).
 * Returns the encrypted key ciphertext needed by the client to unwrap and re-wrap.
 */
export class InviteDataResponseDto {
  @ApiProperty({
    enum: ['active', 'expired', 'claimed', 'revoked'],
    description: 'Current status of the invite',
  })
  status!: string;

  @ApiProperty({
    description: 'Hex-encoded item key wrapped with ephemeral public key',
  })
  encryptedKey!: string;

  @ApiProperty({
    description: 'Array of child keys wrapped with ephemeral public key, or null',
    nullable: true,
  })
  encryptedChildKeys!: Array<{
    keyType: 'file' | 'folder';
    itemId: string;
    encryptedKey: string;
  }> | null;

  @ApiProperty({ enum: ['folder', 'file'] })
  itemType!: string;

  @ApiProperty({ description: 'IPNS name of the shared item' })
  ipnsName!: string;

  @ApiProperty({ description: 'Display name of the shared item' })
  itemName!: string;
}

// ---------------------------------------------------------------------------
// Invite management
// ---------------------------------------------------------------------------

/**
 * Fetch all active invites for a specific item.
 * Uses the authenticated ShareInvitesController endpoint.
 */
export async function fetchInvitesForItem(ipnsName: string): Promise<InviteInfo[]> {
  const response = await shareInvitesControllerListInvites({ ipnsName });
  return response.map((inv) => ({
    id: inv.token, // Use token as ID for revocation (the controller uses inviteId param)
    token: inv.token,
    status: inv.status,
    itemType: inv.itemType,
    ipnsName: inv.ipnsName,
    itemName: inv.itemName,
    expiresAt: String(inv.expiresAt),
    createdAt: String(inv.createdAt),
  }));
}

/**
 * Revoke an active invite link.
 * Only the original sharer can revoke. Already-claimed shares persist.
 */
export async function revokeInvite(inviteId: string): Promise<void> {
  await shareInvitesControllerRevokeInvite(inviteId);
}

